// A knob on A1 sets the brightness of the LED on pin 9
const int POT_PIN = A1;
const int LED_PIN = 9;            // a ~ pin, so analogWrite() makes PWM here
const int BITS = {{p:bits}};      // 10 is the default; the R4's ADC goes up to 14

void setup() {
  Serial.begin(115200);
  analogReadResolution(BITS);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int top = (1 << BITS) - 1;
  int raw = analogRead(POT_PIN);
  float volts = raw * 5.0 / top;
  int duty = map(raw, 0, top, 0, 255);
  analogWrite(LED_PIN, duty);
  Serial.print("A1 = ");
  Serial.print(raw);
  Serial.print("  ");
  Serial.print(volts, 2);
  Serial.println(" V");
  delay(250);
}

